import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  ManyToOne,
} from 'typeorm';
import { PipelineRun } from './pipeline-run.entity';
import { PipelineStep } from './pipeline-step.entity';
import { PipelineStepRunStatus } from '../enums/pipeline-step-run-status.enum';

/**
 * Execution record for one step within a {@link PipelineRun}: the mapped
 * input actually sent, the raw output received, and the cost/latency/error
 * for that single model call.
 */
@Entity('pipeline_step_runs')
export class PipelineStepRun {
  /**
   * Unique UUID identifier generated by the database.
   */
  @PrimaryGeneratedColumn('uuid')
  id: string;

  /**
   * Parent run this step execution belongs to.
   */
  @ManyToOne(() => PipelineRun, (run) => run.stepRuns, { onDelete: 'CASCADE' })
  run: PipelineRun;

  /**
   * The step definition that was executed.
   */
  @ManyToOne(() => PipelineStep, { onDelete: 'CASCADE' })
  step: PipelineStep;

  /**
   * Denormalized step order, for display without joining back to `step`.
   */
  @Column()
  order: number;

  /**
   * The payload after the inbound mapper was applied — what was actually sent to the model.
   */
  @Column({ name: 'mapped_input', type: 'jsonb', nullable: true })
  mappedInput: Record<string, unknown> | null;

  /**
   * The raw output returned by the model.
   */
  @Column({ type: 'jsonb', nullable: true })
  output: Record<string, unknown> | null;

  /**
   * Execution status of this step.
   */
  @Column({
    type: 'varchar',
    enum: PipelineStepRunStatus,
    default: PipelineStepRunStatus.PENDING,
  })
  status: PipelineStepRunStatus;

  /**
   * Credits charged for this step's call.
   */
  @Column({ type: 'decimal', precision: 12, scale: 4, default: 0 })
  cost: number;

  /**
   * Round-trip duration of this step's model call, in milliseconds.
   */
  @Column({ name: 'response_time_ms', type: 'integer', nullable: true })
  responseTimeMs: number | null;

  /**
   * Error message captured if this step failed.
   */
  @Column({ name: 'error_message', type: 'text', nullable: true })
  errorMessage: string | null;

  /**
   * Timestamp record indicating when this step execution was recorded.
   */
  @CreateDateColumn()
  createdAt: Date;
}
